const item = $input.first().json;
const conversion = item?.report?.categories?.conversion;
if (!item.jobId || !item.completionToken || !Number.isInteger(conversion?.score)) {
  throw new Error('invalid-conversion-stage-input');
}
if (conversion.score < 0 || conversion.score > 100) {
  throw new Error('invalid-conversion-score');
}
item.auditStages = [...(item.auditStages || []), 'conversion'];
return [{ json: item }];
